typedef struct {
    HeapNode *data;
    int size;
    int cap;
} Heap;

void heap_push(Heap *h, int v, ll dist) {
    if (h->size == h->cap) {
        h->cap = h->cap ? h->cap * 2 : 4;
        h->data = realloc(h->data, sizeof(HeapNode) * h->cap);
    }
    int i = h->size++;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (h->data[p].dist <= dist) break;
        h->data[i] = h->data[p];
        i = p;
    }
    h->data[i].v = v;
    h->data[i].dist = dist;
}

HeapNode heap_pop(Heap *h) {
    HeapNode ret = h->data[0];
    HeapNode last = h->data[--h->size];
    int i = 0;
    while (1) {
        int left = 2 * i + 1;
        int right = 2 * i + 2;
        int smallest = i;
        if (left < h->size && h->data[left].dist < h->data[smallest].dist) smallest = left;
        if (right < h->size && h->data[right].dist < h->data[smallest].dist) smallest = right;
        if (smallest == i) break;
        h->data[i] = h->data[smallest];
