            add_edge(from, seg_id[dir][node], cost);
        else
            add_edge(seg_id[dir][node], from, cost);
        return;
    }
    int mid = (l + r) / 2;
    add_range(node * 2, l, mid, ql, qr, from, cost, dir);
    add_range(node * 2 + 1, mid + 1, r, ql, qr, from, cost, dir);
}

