        add_range(1, 1, seg_nodes, L, R, L, C, 0);
        add_range(1, 1, seg_nodes, L, R, R, C, 1);
    }

    // dijkstra
    ll *dist = malloc(sizeof(ll) * (tot_nodes + 1));
    for (int i = 1; i <= tot_nodes; i++) dist[i] = INF;
    dist[1] = 0;

    Heap h = {0};
    heap_push(&h, 1, 0);

