static void heap_push(HeapNode *heap, int *sz, ll d, int v) {
    int i = ++(*sz);
    while (i > 1) {
        int p = i >> 1;
        if (heap[p].d <= d) break;
        heap[i] = heap[p];
        i = p;
    }
    heap[i].d = d;
    heap[i].v = v;
}

static HeapNode heap_pop(HeapNode *heap, int *sz) {
    HeapNode ret = heap[1];
    HeapNode last = heap[(*sz)--];
    int i = 1;
    while ((i << 1) <= *sz) {
        int l = i << 1, r = l + 1, c = l;
        if (r <= *sz && heap[r].d < heap[l].d) c = r;
        if (heap[c].d >= last.d) break;
        heap[i] = heap[c];
        i = c;
    }
    heap[i] = last;
    return ret;
}

