    // Build segment tree with 4N nodes, indexed from 1
    int size = 1;
    while (size < N) size *= 2;
    int total_nodes = 2 * size + 2 * size + 5; // upper and lower trees + original nodes
    int offset_up = size;
    int offset_down = size * 3;

    vector<vector<Edge>> g(offset_down + 2 * size + 5);

    // connect leaf nodes to original vertices
    for (int i = 0; i < N; i++) {
        int leaf_up = offset_up + i;
        int leaf_down = offset_down + i;
        g[i].push_back({leaf_up, 0});
        g[leaf_down].push_back({i, 0});
    }

    // build up-tree edges (child to parent with cost 0)
    for (int i = size - 1; i >= 1; i--) {
        int left = 2 * i, right = 2 * i + 1;
        g[offset_up + left].push_back({offset_up + i, 0});
        g[offset_up + right].push_back({offset_up + i, 0});
    }

    // build down-tree edges (parent to child with cost 0)
    for (int i = 1; i < size; i++) {
        int left = 2 * i, right = 2 * i + 1;
        g[offset_down + i].push_back({offset_down + left, 0});
        g[offset_down + i].push_back({offset_down + right, 0});
    }

    auto add_range_up = [&](int l, int r, int virt, ll cost) {
        l += size; r += size;
        while (l < r) {
            if (l & 1) {
                g[offset_up + l].push_back({virt, cost});
                l++;
            }
            if (r & 1) {
                r--;
                g[offset_up + r].push_back({virt, cost});
            }
            l >>= 1; r >>= 1;
        }
    };

    auto add_range_down = [&](int l, int r, int virt, ll cost) {
        l += size; r += size;
        while (l < r) {
            if (l & 1) {
                g[virt].push_back({offset_down + l, cost});
                l++;
            }
            if (r & 1) {
                r--;
                g[virt].push_back({offset_down + r, cost});
            }
            l >>= 1; r >>= 1;
        }
    };

    int virt_id = offset_down + 2 * size; // start assigning virtual nodes

    for (int i = 0; i < M; i++) {
        int L, R; ll C;
        cin >> L >> R >> C;
        L--; R--;
        int virt = virt_id++;
        // from down-tree range to virt with cost C
        add_range_down(L, R+1, virt, C);
        // from virt to up-tree range with cost 0
        add_range_up(L, R+1, virt, 0);
    }

    // Dijkstra from vertex 0
    vector<ll> dist(virt_id, INF);
    dist[0] = 0;
    priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
    pq.push({0, 0});

    while (!pq.empty()) {
        auto [d, v] = pq.top(); pq.pop();
        if (d != dist[v]) continue;
        for (auto &e : g[v]) {
            if (dist[e.to] > d + e.cost) {
                dist[e.to] = d + e.cost;
                pq.push({dist[e.to], e.to});
            }
        }
    }

    ll ans = dist[N-1];
    if (ans == INF) cout << -1 << "\n";
    else cout << ans << "\n";

    return 0;
}

