// leaves of both trees connect: up_leaf -> actual vertex, actual vertex -> down_leaf (or same node)

// Let's use sz = next power of 2 >= N
// down tree nodes: 1..2*sz-1
// up tree nodes: 2*sz..4*sz-1
// actual vertices: leaves of down tree = sz..2*sz-1 (vertex i -> node sz+i-1)

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> N >> M;

    sz = 1;
    while(sz < N) sz <<= 1;

    int total = 4*sz + 5;
    vector<vector<pair<int,ll>>> g(total);

    // down tree: parent -> children, cost 0
    for(int i = 1; i < sz; i++){
        g[i].push_back({2*i, 0});
        g[i].push_back({2*i+1, 0});
    }
    // up tree: children -> parent, cost 0. Offset = 2*sz
    int off = 2*sz;
    for(int i = 1; i < sz; i++){
        g[off+2*i].push_back({off+i, 0});
        g[off+2*i+1].push_back({off+i, 0});
    }
    // connect leaves: up_leaf[i] -> down_leaf[i], cost 0
    for(int i = 0; i < sz; i++){
        g[off+sz+i].push_back({sz+i, 0});
    }

    auto get_down_nodes = [&](int l, int r, vector<int>& nodes){
        for(l+=sz-1, r+=sz; l<r; l>>=1, r>>=1){
            if(l&1) nodes.push_back(l++);
            if(r&1) nodes.push_back(--r);
        }
    };
    auto get_up_nodes = [&](int l, int r, vector<int>& nodes){
        for(l+=sz-1+off, r+=sz+off; l<r; l>>=1, r>>=1){
            if(l&1) nodes.push_back(l++);
            if(r&1) nodes.push_back(--r);
        }
    };

    for(int i = 0; i < M; i++){
        int L, R; ll C;
        cin >> L >> R >> C;
        vector<int> up_nodes, down_nodes;
        get_up_nodes(L, R, up_nodes);
        get_down_nodes(L, R, down_nodes);
        for(int u : up_nodes)
            for(int v : down_nodes)
                g[u].push_back({v, C});
    }

    int src = sz + 0; // vertex 1 -> index sz+0
    int dst = sz + N - 1;

    vector<ll> dist(total, INF);
    priority_queue<pli, vector<pli>, greater<pli>> pq;
    dist[src] = 0; dist[off+src-sz+sz] = 0;
    // src in down tree = sz, src in up tree = off+sz
    dist[sz] = 0; dist[off+sz] = 0;
    pq.push({0, sz});
    pq.push({0, off+sz});

    while(!pq.empty()){
        auto [d,u] = pq.top(); pq.pop();
        if(d > dist[u]) continue;
        for(auto [v,w] : g[u]){
            if(dist[u]+w < dist[v]){
                dist[v] = dist[u]+w;
                pq.push({dist[v],v});
            }
        }
    }

    ll ans = min(dist[dst], dist[off+dst-sz+sz]);
    // dst in down tree = sz+N-1, in up tree = off+sz+N-1
    ans = min(ans, dist[off+sz+N-1]);
    cout << (ans == INF ? -1 : ans) << "\n";
}

