    buildDown(1, 1, N);

    function<void(int,int,int,int,int,int)> addFromRangeToNode =
        [&](int idx, int l, int r, int ql, int qr, int node) {
            if (qr < l || r < ql) return;
            if (ql <= l && r <= qr) {
                g[down[idx]].push_back({node, 0});
                return;
            }
            int mid = (l + r) >> 1;
            addFromRangeToNode(idx << 1, l, mid, ql, qr, node);
            addFromRangeToNode(idx << 1 | 1, mid + 1, r, ql, qr, node);
        };

    function<void(int,int,int,int,int,int)> addFromNodeToRange =
        [&](int idx, int l, int r, int ql, int qr, int node) {
            if (qr < l || r < ql) return;
            if (ql <= l && r <= qr) {
                g[node].push_back({up[idx], 0});
                return;
            }
            int mid = (l + r) >> 1;
            addFromNodeToRange(idx << 1, l, mid, ql, qr, node);
            addFromNodeToRange(idx << 1 | 1, mid + 1, r, ql, qr, node);
        };

    for (int L = 1; L <= N; ++L) {
        for (auto [R, C] : startAt[L]) {
            int inNode = newNode();
            int outNode = newNode();

            // any vertex in [L,R] -> inNode
            addFromRangeToNode(1, 1, N, L, R, inNode);
            // outNode -> any vertex in [L,R]
            addFromNodeToRange(1, 1, N, L, R, outNode);

            // choosing an edge inside the clique costs C
            g[inNode].push_back({outNode, C});
            g[outNode].push_back({inNode, C});
        }
    }

    int S = orig[1], T = orig[N];
    vector<ll> dist(g.size(), INF);
    priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;

    dist[S] = 0;
    pq.push({0, S});

    while (!pq.empty()) {
        auto [d, v] = pq.top();
        pq.pop();
        if (d != dist[v]) continue;
        if (v == T) break;
        for (auto &e : g[v]) {
            if (dist[e.to] > d + e.w) {
                dist[e.to] = d + e.w;
                pq.push({dist[e.to], e.to});
            }
        }
    }

    if (dist[T] == INF) cout << -1 << '\n';
    else cout << dist[T] << '\n';

    return 0;
}

