    static void addFromOpToRangeOut(int idx, int ql, int qr, int opId) {
        NodeRange cur = outSeg[idx];
        if (cur == null || qr < cur.l || cur.r < ql) return;
        if (ql <= cur.l && cur.r <= qr) {
