        }
        addFromOpToRangeOut(idx << 1, ql, qr, opId);
        addFromOpToRangeOut(idx << 1 | 1, ql, qr, opId);
    }

    static void addFromRangeInToOp(int idx, int ql, int qr, int opId, long cost) {
        NodeRange cur = inSeg[idx];
        if (cur == null || qr < cur.l || cur.r < ql) return;
