        for (int i = 1; i <= N; i++) {
            addEdge(outLeaf[i], inLeaf[i], 0);
            addEdge(inLeaf[i], outLeaf[i], 0);
        }

        int start = outLeaf[1];
        int target = outLeaf[N];

        long INF = Long.MAX_VALUE / 4;
        long[] dist = new long[nextId];
        Arrays.fill(dist, INF);
        PriorityQueue<State> pq = new PriorityQueue<>();
        dist[start] = 0;
