            if (cur.v == target) break;
            for (Edge e : g.get(cur.v)) {
                long nd = cur.d + e.w;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.add(new State(e.to, nd));
                }
            }
        }

        System.out.println(dist[target] >= INF ? -1 : dist[target]);
